package com.lr.sunnysprout;
import android.app.*;import android.widget.Toast;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import java.io.*;
public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> files; String pending;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xfffaf8f1);getWindow().setNavigationBarColor(0xfffaf8f1);getWindow().getDecorView().setSystemUiVisibility(0x2000|0x10);web=new WebView(this);setContentView(web);web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});web.setWebChromeClient(new WebChromeClient(){public boolean onJsConfirm(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setNegativeButton("取消",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,1);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}});web.loadUrl("file:///android_asset/index.html");}
 class Bridge {@JavascriptInterface public String load(){return getPreferences(0).getString("journal","");}@JavascriptInterface public boolean save(String data){return getPreferences(0).edit().putString("journal",data).commit();}@JavascriptInterface public void exportBackup(String data){runOnUiThread(()->{pending=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"晴芽备份-"+java.time.LocalDate.now()+".json");startActivityForResult(i,2);});}@JavascriptInterface public void importBackup(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,3);});}@JavascriptInterface public void haptic(){runOnUiThread(()->web.performHapticFeedback(0));}}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1){if(files!=null){files.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);files=null;}return;}if(result!=RESULT_OK||data==null)return;try{if(req==2){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pending.getBytes("UTF-8"));}pending=null;Toast.makeText(this,"备份已保存，照片也在里面",0).show();}if(req==3){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(data.getData())){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>32*1024*1024)throw new IOException("too large");out.write(buf,0,n);}}String s=out.toString("UTF-8");web.evaluateJavascript("importData("+org.json.JSONObject.quote(s)+")",null);}}catch(Exception e){Toast.makeText(this,"操作失败，请检查文件或存储空间",1).show();}}
 @Override public void onBackPressed(){web.evaluateJavascript("goBack()",null);}
}
